(function(){"use strict";var BOX_ID="seo-primary-box";var overrides=null;var fleet=null;function api(path,options){var token=localStorage.getItem("adminToken");var opts=options||{};opts.headers=Object.assign({"Content-Type":"application/json"},opts.headers||{},token?{Authorization:"Bearer "+token}:{});return fetch((window.API_BASE_URL||"")+path,opts).then(function(r){return r.json()})}function groupKey(car){return[car.make_name,car.model_name,car.production_year].map(function(v){return String(v==null?"":v).trim().toLowerCase()}).join("|")}function byAge(a,b){var ta=Date.parse(a.created_at||"")||0;var tb=Date.parse(b.created_at||"")||0;if(ta!==tb)return ta-tb;return Number(a.id)-Number(b.id)}function duplicatesOf(car){var key=groupKey(car);return(fleet||[]).filter(function(c){return groupKey(c)===key}).sort(byAge)}function primaryIdFor(car){var group=duplicatesOf(car);if(group.length<2)return null;var chosen=overrides&&overrides[groupKey(car)];if(chosen!=null){var hit=group.find(function(c){return String(c.id)===String(chosen)});if(hit)return String(hit.id)}return String(group[0].id)}function label(car){var name=[car.make_name,car.model_name,car.production_year].filter(Boolean).join(" ");return name+" (#"+car.id+")"}function css(){if(document.getElementById("seo-primary-css"))return;var st=document.createElement("style");st.id="seo-primary-css";st.textContent="#"+BOX_ID+"{margin:18px 0;padding:16px 18px;border:1px solid #fde68a;"+"border-left:4px solid #f59e0b;border-radius:10px;background:#fffbeb}"+"#"+BOX_ID+" h6{margin:0 0 6px;font-size:.92rem;font-weight:800;color:#7c2d12}"+"#"+BOX_ID+" p{margin:0 0 10px;font-size:.84rem;line-height:1.55;color:#92400e}"+"#"+BOX_ID+" select{width:100%;max-width:420px;padding:9px 11px;border:1px solid #fcd34d;"+"border-radius:8px;background:#fff;font-size:.9rem;color:#1c1917}"+"#"+BOX_ID+" .sp-state{display:block;margin-top:9px;font-size:.82rem;font-weight:700}"+"#"+BOX_ID+" .sp-yes{color:#15803d}"+"#"+BOX_ID+" .sp-no{color:#92400e}";document.head.appendChild(st)}function render(car){var host=document.getElementById("editCarForm");var old=document.getElementById(BOX_ID);if(old)old.remove();if(!host||!car)return;var group=duplicatesOf(car);if(group.length<2)return;css();var currentPrimary=primaryIdFor(car);var isThisOne=String(currentPrimary)===String(car.id);var box=document.createElement("div");box.id=BOX_ID;box.innerHTML="<h6>Pagina indexată pentru acest model</h6>"+"<p>Ai "+group.length+" mașini identice ("+[car.make_name,car.model_name,car.production_year].filter(Boolean).join(" ")+"). Toate se pot rezerva normal, dar Google indexează doar una, ca să nu "+"concureze între ele. Alege care.</p>"+'<select id="sp-select"></select>'+'<span class="sp-state '+(isThisOne?"sp-yes":"sp-no")+'">'+(isThisOne?"Mașina asta este pagina indexată.":"Mașina asta trimite către mașina aleasă mai sus.")+"</span>";var sel=box.querySelector("#sp-select");group.forEach(function(c){var o=document.createElement("option");o.value=String(c.id);o.textContent=label(c)+(String(c.id)===String(car.id)?" — cea deschisă acum":"");if(String(c.id)===String(currentPrimary))o.selected=true;sel.appendChild(o)});sel.addEventListener("change",function(){api("/api/cars/seo-primary",{method:"POST",body:JSON.stringify({group_key:groupKey(car),car_id:sel.value})}).then(function(res){if(res&&res.success){overrides=res.overrides||{};if(typeof window.showCustomAlert==="function"){window.showCustomAlert("Pagina indexată a fost schimbată.","success")}render(car)}else if(typeof window.showCustomAlert==="function"){window.showCustomAlert(res&&res.error||"Nu s-a putut salva.","error")}}).catch(function(){if(typeof window.showCustomAlert==="function"){window.showCustomAlert("Nu s-a putut salva.","error")}})});var anchor=document.getElementById("editGalleryImagesPreview");var place=anchor&&anchor.parentElement?anchor.parentElement:host;place.appendChild(box)}function load(){return Promise.all([fleet?Promise.resolve(fleet):api("/api/cars").then(function(r){fleet=Array.isArray(r)?r:r&&r.cars||[];return fleet}),overrides?Promise.resolve(overrides):api("/api/cars/seo-primary").then(function(r){overrides=r&&r.overrides||{};return overrides})])}window.showSeoPrimaryControl=function(car){if(!car)return;fleet=null;overrides=null;load().then(function(){var fresh=(fleet||[]).find(function(c){return String(c.id)===String(car.id)});render(fresh||car)}).catch(function(){})}})();